    // Scrolling over a focused number input silently changes its value — blur so the wheel just scrolls.
    document.addEventListener('wheel', (e) => {
      const el = document.activeElement;
      if (el && el.tagName === 'INPUT' && el.type === 'number' && el.contains(e.target)) el.blur();
    }, { passive: true });

    function getSessionId() {
      let id = localStorage.getItem('cart_session_id');
      if (!id) {
        // crypto.randomUUID is secure-context-only (and iOS Safari 15.4+) — absent on
        // http:// LAN/IP visits and older mobile browsers; without the fallback the
        // whole app crashes at mount ("Something Went Wrong" on every page).
        id = 'sess_' + ((window.crypto && crypto.randomUUID) ? crypto.randomUUID() : (Math.random().toString(36).slice(2) + Date.now().toString(36)));
        try { localStorage.setItem('cart_session_id', id); } catch(e) { /* quota exceeded */ }
      }
      return id;
    }

    function generateSlug(text) {
      return (text || '').toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    }

    // Progressive US phone formatter → "(XXX) XXX-XXXX" (+1 country code, " x<ext>" beyond 10 digits). Null-safe.
    // Module-level fallback used by phone fields whose component has no local formatter.
    function formatPhone(val) {
      let d = (val || '').replace(/\D/g, '');
      let cc = '';
      if (d.length > 10 && d[0] === '1') { cc = '+1 '; d = d.slice(1); }
      const ext = d.slice(10);
      d = d.slice(0, 10);
      let out;
      if (d.length < 4) out = d;
      else if (d.length < 7) out = '(' + d.slice(0, 3) + ') ' + d.slice(3);
      else out = '(' + d.slice(0, 3) + ') ' + d.slice(3, 6) + '-' + d.slice(6);
      return (cc + out + (ext ? ' x' + ext : '')).trim();
    }

