    // Shown when a logged-in customer has no phone on file (e.g. Google sign-up,
    // which doesn't provide one). Required — no dismiss — so we can reach them
    // about orders before they shop/checkout.
    function CompleteProfileModal({ customer, customerToken, setCustomer }) {
      const [phone, setPhone] = useState('');
      const [company, setCompany] = useState(customer.company_name || '');
      const [error, setError] = useState('');
      const [saving, setSaving] = useState(false);
      const save = async () => {
        setError('');
        if (phone.replace(/\D/g, '').length < 10) { setError('Please enter a valid 10-digit phone number.'); return; }
        setSaving(true);
        try {
          const res = await fetch(API + '/api/customer/profile', {
            method: 'PUT', headers: { 'Content-Type': 'application/json', 'X-Customer-Token': customerToken },
            body: JSON.stringify({ phone, company_name: company })
          });
          const data = await res.json();
          if (!res.ok || data.error) { setError(data.error || 'Could not save. Please try again.'); setSaving(false); return; }
          setCustomer(data.customer);
        } catch (e) { setError('Could not save. Please try again.'); setSaving(false); }
      };
      return (
        <div className="modal-overlay">
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <h2>One more thing</h2>
            <p style={{ color: 'var(--stone-600)', fontSize: '0.9rem', marginBottom: '1.5rem' }}>
              Welcome{customer.first_name ? ', ' + customer.first_name : ''}! Add a phone number so we can reach you about orders and deliveries.
            </p>
            {error && <div className="checkout-error">{error}</div>}
            <div className="checkout-field"><label>Phone *</label>
              <input className="checkout-input" type="tel" value={phone} onChange={e => setPhone(formatPhone(e.target.value))} placeholder="(555) 123-4567" autoComplete="tel" autoFocus /></div>
            <div className="checkout-field" style={{ marginTop: '0.75rem' }}><label>Company (optional)</label>
              <input className="checkout-input" value={company} onChange={e => setCompany(e.target.value)} autoComplete="organization" /></div>
            <button onClick={save} disabled={saving}
              style={{ marginTop: '1.5rem', width: '100%', padding: '0.85rem', background: 'var(--stone-900)', color: '#fff', border: 'none', borderRadius: 8, fontSize: '0.95rem', cursor: saving ? 'default' : 'pointer', fontFamily: 'Inter, sans-serif' }}>
              {saving ? 'Saving…' : 'Save & continue'}
            </button>
          </div>
        </div>
      );
    }

    // ==================== Installation Modal ====================

    function InstallationModal({ onClose, product }) {
      const [name, setName] = useState('');
      const [email, setEmail] = useState('');
      const [phone, setPhone] = useState('');
      const [companyName, setCompanyName] = useState('');
      const [zipCode, setZipCode] = useState('');
      const [sqft, setSqft] = useState('');
      const [message, setMessage] = useState('');
      const [submitted, setSubmitted] = useState(false);
      const [error, setError] = useState('');
      useEffect(() => { document.body.style.overflow = 'hidden'; return () => { document.body.style.overflow = ''; }; }, []);

      const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        if (name.trim().split(/\s+/).length < 2) { setError('Please enter a first and last name.'); return; }
        try {
          const body = { customer_name: name, customer_email: email, phone, company_name: companyName, zip_code: zipCode, estimated_sqft: sqft || null, message };
          if (product) { body.product_id = product.product_id; body.sku_id = product.sku_id; body.product_name = product.product_name; body.collection = product.collection; }
          const res = await fetch(API + '/api/installation-inquiries', {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
          });
          const data = await res.json();
          if (data.error) { setError(data.error); return; }
          setSubmitted(true);
        } catch(e) { setError('Unable to submit. Please try again.'); }
      };

      return (
        <div className="modal-overlay" onClick={onClose}>
          <div className="modal-content" onClick={e => e.stopPropagation()}>
            <button className="modal-close" onClick={onClose}>&times;</button>
            {submitted ? (
              <div style={{ textAlign: 'center', padding: '2rem 0' }}>
                <div style={{ width: 60, height: 60, borderRadius: '50%', background: '#d1fae5', display: 'flex', alignItems: 'center', justifyContent: 'center', margin: '0 auto 1.5rem' }}>
                  <svg viewBox="0 0 24 24" fill="none" stroke="#059669" strokeWidth="2" style={{ width: 30, height: 30 }}><polyline points="20 6 9 17 4 12"/></svg>
                </div>
                <h2 style={{ marginBottom: '0.5rem' }}>Thank You!</h2>
                <p style={{ color: 'var(--stone-600)', fontSize: '0.95rem' }}>We'll be in touch within 1 business day.</p>
              </div>
            ) : (
              <>
                <h2>Request Installation Quote</h2>
                {product && <p style={{ color: 'var(--stone-600)', fontSize: '0.875rem', marginBottom: '1.5rem' }}>For: {fullProductName(product)}</p>}
                <form onSubmit={handleSubmit}>
                  {error && <div className="checkout-error">{error}</div>}
                  <div className="checkout-field"><label>Name *</label><input className="checkout-input" value={name} onChange={e => setName(e.target.value)} required /></div>
                  <div className="checkout-row">
                    <div className="checkout-field"><label>Email *</label><input className="checkout-input" type="email" value={email} onChange={e => setEmail(e.target.value)} required /></div>
                    <div className="checkout-field"><label>Phone *</label><input className="checkout-input" type="tel" value={phone} onChange={e => setPhone(formatPhone(e.target.value))} required /></div>
                  </div>
                  <div className="checkout-field"><label>Company (optional)</label><input className="checkout-input" value={companyName} onChange={e => setCompanyName(e.target.value)} autoComplete="organization" /></div>
                  <div className="checkout-row">
                    <div className="checkout-field"><label>ZIP Code</label><input className="checkout-input" value={zipCode} onChange={e => setZipCode(e.target.value)} maxLength={5} /></div>
                    <div className="checkout-field"><label>Est. Square Feet</label><input className="checkout-input" type="number" value={sqft} onChange={e => setSqft(e.target.value)} /></div>
                  </div>
                  <div className="checkout-field"><label>Message</label><textarea className="checkout-input" value={message} onChange={e => setMessage(e.target.value)} rows={3} style={{ resize: 'vertical' }} /></div>
                  <button type="submit" className="btn" style={{ width: '100%' }}>Submit Inquiry</button>
                </form>
              </>
            )}
          </div>
        </div>
      );
    }

    // ==================== Installation Landing Page ====================

    // Inline quote form (mirrors InstallationModal's fields + POST target for on-page conversion)
    function InstallQuoteForm() {
      const [name, setName] = useState('');
      const [email, setEmail] = useState('');
      const [phone, setPhone] = useState('');
      const [companyName, setCompanyName] = useState('');
      const [zipCode, setZipCode] = useState('');
      const [sqft, setSqft] = useState('');
      const [message, setMessage] = useState('');
      const [submitted, setSubmitted] = useState(false);
      const [error, setError] = useState('');
      const [saving, setSaving] = useState(false);

      const handleSubmit = async (e) => {
        e.preventDefault();
        setError('');
        if (name.trim().split(/\s+/).length < 2) { setError('Please enter a first and last name.'); return; }
        setSaving(true);
        try {
          const body = { customer_name: name, customer_email: email, phone, company_name: companyName, zip_code: zipCode, estimated_sqft: sqft || null, message };
          const res = await fetch(API + '/api/installation-inquiries', {
            method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body)
          });
          const data = await res.json();
          if (data.error) { setError(data.error); setSaving(false); return; }
          setSubmitted(true);
        } catch(e) { setError('Unable to submit. Please try again.'); setSaving(false); }
      };

      if (submitted) return (
        <div className="install-form-success">
          <div className="install-form-success-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="#059669" strokeWidth="2"><polyline points="20 6 9 17 4 12"/></svg>
          </div>
          <h3>Thank You!</h3>
          <p>Your request is in — we'll be in touch within 1 business day.</p>
        </div>
      );

      return (
        <form className="install-quote-form" onSubmit={handleSubmit}>
          {error && <div className="checkout-error">{error}</div>}
          <div className="checkout-field"><label>Name *</label><input className="checkout-input" value={name} onChange={e => setName(e.target.value)} required /></div>
          <div className="checkout-row">
            <div className="checkout-field"><label>Email *</label><input className="checkout-input" type="email" value={email} onChange={e => setEmail(e.target.value)} required /></div>
            <div className="checkout-field"><label>Phone *</label><input className="checkout-input" type="tel" value={phone} onChange={e => setPhone(formatPhone(e.target.value))} required /></div>
          </div>
          <div className="checkout-field"><label>Company (optional)</label><input className="checkout-input" value={companyName} onChange={e => setCompanyName(e.target.value)} autoComplete="organization" /></div>
          <div className="checkout-row">
            <div className="checkout-field"><label>ZIP Code</label><input className="checkout-input" value={zipCode} onChange={e => setZipCode(e.target.value)} maxLength={5} /></div>
            <div className="checkout-field"><label>Est. Square Feet</label><input className="checkout-input" type="number" value={sqft} onChange={e => setSqft(e.target.value)} /></div>
          </div>
          <div className="checkout-field"><label>Project details</label><textarea className="checkout-input" value={message} onChange={e => setMessage(e.target.value)} rows={3} placeholder="Flooring type, rooms, timeline…" style={{ resize: 'vertical' }} /></div>
          <button type="submit" className="btn btn-gold" disabled={saving} style={{ width: '100%' }}>{saving ? 'Submitting…' : 'Request My Free Quote'}</button>
        </form>
      );
    }

    function InstallFAQ({ items = INSTALL_FAQ }) {
      const [open, setOpen] = useState(0);
      return (
        <div className="install-faq-list">
          {items.map(([q, a], i) => (
            <div key={i} className={'install-faq-item' + (open === i ? ' open' : '')}>
              <button className="install-faq-q" onClick={() => setOpen(open === i ? -1 : i)} aria-expanded={open === i}>
                <span>{q}</span>
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polyline points="6 9 12 15 18 9"/></svg>
              </button>
              {open === i && <div className="install-faq-a">{a}</div>}
            </div>
          ))}
        </div>
      );
    }

    function InstallReviews() {
      if (!INSTALL_REVIEWS || !INSTALL_REVIEWS.reviewCount) return null;
      return (
        <div className="install-reviews">
          <h2>What Orange County Homeowners Say</h2>
          <div className="install-reviews-rating">
            <span className="install-stars" aria-hidden="true">★★★★★</span>
            <span>{INSTALL_REVIEWS.ratingValue} · {INSTALL_REVIEWS.reviewCount} Google reviews</span>
          </div>
          <div className="install-reviews-grid">
            {(INSTALL_REVIEWS.items || []).map((r, i) => (
              <blockquote key={i} className="install-review-card">
                <div className="install-stars" aria-hidden="true">{'★'.repeat(Math.round(r.rating || INSTALL_REVIEWS.ratingValue))}</div>
                <p>“{r.text}”</p>
                <cite>— {r.author}</cite>
              </blockquote>
            ))}
          </div>
        </div>
      );
    }

